import { createContext, useState, useContext } from "react";

const AuthContext = createContext();

function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    const saved = localStorage.getItem("artframe_user");
    return saved ? JSON.parse(saved) : null;
  });
  const [token, setToken] = useState(() => localStorage.getItem("artframe_token") || null);

  const login = (tokenValue, userData) => {
    setToken(tokenValue); setUser(userData);
    localStorage.setItem("artframe_token", tokenValue);
    localStorage.setItem("artframe_user", JSON.stringify(userData));
  };

  const logout = () => {
    setToken(null); setUser(null);
    localStorage.removeItem("artframe_token");
    localStorage.removeItem("artframe_user");
  };

  return (
    <AuthContext.Provider value={{ user, token, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

function useAuth() { return useContext(AuthContext); }
export { AuthProvider, useAuth };
